#include<bits/stdc++.h>
using namespace std;

#define ll long long

int main(){

    int tt = 1;
    cin >> tt;

    while(tt--){
        ll n;
        cin >> n;

        vector<ll> a(n);
        for(ll i = 0; i < n; i++) cin >> a[i];

        vector<vector<ll>> v(n);
        for(ll i = 1; i < n; i++){
            ll x, y;
            cin >> x >> y;
            x--;
            y--;
            v[x].push_back(y);
            v[y].push_back(x);
        }

        ll ans = 0;
        vector<ll> ss(n, 1);

        function<void(ll, ll)> dfs = [&](ll u, ll par){

            vector<ll> val;
            for(auto& z : v[u]) if(z != par){
                dfs(z, u);
                val.push_back(ss[z]);
                ss[u] += ss[z];
            }

            val.push_back(n - ss[u]);
            assert(accumulate(val.begin(), val.end(), 0ll) == n - 1);

            if((ll)sqrtl(a[u]) * (ll)sqrtl(a[u]) < a[u]) return;

            ll sum = 0;
            ll pairs = 0;
            ll triplets = 0;

            for(auto& z : val){
                triplets += pairs * z;
                pairs += sum * z;
                sum += z;
            }

            ans += pairs;
            ans += triplets;
        };

        dfs(0, -1);

        cout << ans << '\n';
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;

#define ll long long

int main(){

    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int tt = 1;
    cin >> tt;

    while(tt--){
        ll n;
        cin >> n;

        string s;
        cin >> s;

        bool is = 1;
        int left = 0, right = n - 1;

        while(left < n && s[left] == '0') left++;
        while(right >= 0 && s[right] == '1') right--;

        if(left > right){
            cout << "Bob\n";
            continue;
        }

        int count = 1;
        for(int i = left; i < right; i++){
            if(s[i + 1] == s[i]) count++;
            else{
                if(count % 2 == 1) is = 0;
                count = 1;
            }
        }

        if(count % 2 == 1) is = 0;

        cout << (is ? "Bob\n" : "Alice\n");
    }

    return 0;
}

#include<bits/stdc++.h>
using namespace std;

#define ll long long
typedef __int128 int128;

std::ostream& operator<<(std::ostream& os, int128 t) {
    if (t == 0) return os << "0";
    if (t < 0) {
        os << "-";
        t = -t;
    }
    int a[50], i = 0;
    while (t > 0) {
        a[i++] = t % 10;
        t /= 10;
    }
    for (int j = i - 1; j >= 0; j--) {
        os << (char)(a[j] + '0');
    }
    return os;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int tt = 1;
    cin >> tt;

    while(tt--){
        ll n;
        cin >> n;

        vector<ll> a(n);
        for(auto& z : a) cin >> z;

        int128 ans = 0;
        stack<ll> s;

        for(int i = 0; i < n; i++){
            while(!s.empty() && a[i] % a[s.top()] > 0){
                ans += (int128)1 * (n - i) * min(a[i] % a[s.top()], a[s.top()] - a[i] % a[s.top()]);
                s.pop();
            }
            s.push(i);
        }

        cout << ans << '\n';
    }

    return 0;
}
